import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { gunzipSync } from 'node:zlib'
import { Client } from 'pg'
import { describe, expect, it } from 'vitest'

import { ASSETS } from '../../../scripts/seed/asset_registry_seed'

const migrationPath = path.resolve(process.cwd(),
  'supabase/migrations/608_nirmana_bg_remedies_integrity_contract.sql')
const migration = fs.existsSync(migrationPath) ? fs.readFileSync(migrationPath, 'utf8') : ''
const EXPECTED_ID_MD5 = '8bac868a1b9708eedee44a7266237d08'
const CANONICAL_VOLUME = '341 achieved remedies from the frozen deterministic build: 283 static writer rows + 54 bg_texts-derived sweep rows + 4 accepted tantric rows. Integrity enforces exact source-derived identity and closed taxonomies; ZERO LLM and ZERO fabrication.'
const CANONICAL_DESCRIPTION = 'Classical remedies: mantras, gemstones, charity, vrata, yantras, puja, tantric, ayurvedic, vastu, behavioral'
// Exact 54-row read-only source snapshot used by frozen definition
// t0-2026-08-25-4a78a5c4; compressed to keep the integration test self-contained.
const SOURCE_CHUNKS_GZIP_BASE64 = ''
const SOURCE_CHUNKS = JSON.parse(gunzipSync(Buffer.from(
  SOURCE_CHUNKS_GZIP_BASE64, 'base64')).toString('utf8')) as Array<{
  chunk_id: string; text_id: string; source_citation: string | null; content_en: string
}>

describe('migration 608 — bg_remedies governed rebuild contract', () => {
  it('is runner-owned, corpus-preserving, and aligned with the replay seed', () => {
    const remedies = ASSETS.find(asset => asset.asset_id === 'bg_remedies')
    expect(SOURCE_CHUNKS).toHaveLength(54)
    expect(remedies?.depends_on).toEqual(['bg_texts'])
    expect(remedies?.target_floor).toBe(341)
    expect(remedies?.volume_explanation).toBe(CANONICAL_VOLUME)
    expect(remedies?.english_description).toBe(CANONICAL_DESCRIPTION)
    expect(migration).toContain('migration 608 refuses unknown bg_remedies registry contract')
    expect(migration).toContain(EXPECTED_ID_MD5)
    expect(migration).not.toMatch(/^BEGIN;/m)
    expect(migration).not.toMatch(/^COMMIT;/m)
    expect(migration).not.toMatch(/(?:INSERT INTO|UPDATE|DELETE FROM)\s+brahma_remedy_corpus/i)
  })
})

const TEST_DATABASE_URL = process.env.NIRMANA_BG_REMEDIES_INTEGRITY_TEST_DATABASE_URL
if (TEST_DATABASE_URL) {
  const parsed = new URL(TEST_DATABASE_URL)
  if (!['localhost', '127.0.0.1'].includes(parsed.hostname)
    || parsed.pathname !== '/nirmana_bg_remedies_integrity_test') {
    throw new Error('NIRMANA_BG_REMEDIES_INTEGRITY_TEST_DATABASE_URL must point to '
      + 'the exact local nirmana_bg_remedies_integrity_test database')
  }
}

describe.skipIf(!TEST_DATABASE_URL)('migration 608 — real Postgres behavior', () => {
  async function connectPrepared(): Promise<Client> {
    const client = new Client({ connectionString: TEST_DATABASE_URL })
    await client.connect()
    await client.query(`
      DROP TABLE IF EXISTS asset_registry, remedy_review_queue,
        brahma_remedy_corpus, classical_text_chunks CASCADE;
      CREATE TABLE classical_text_chunks (
        chunk_id text PRIMARY KEY, text_id text, source_citation text, content_en text);
      CREATE TABLE brahma_remedy_corpus (
        remedy_id text PRIMARY KEY, planet text, domain text, remedy_type text,
        prescription_text text, mantra_text text, gemstone text, charity_action text,
        day_of_week text, color_associated text, confidence numeric,
        source_canonical_id text, source_citation text, classical_ref text,
        category text, deity text, mantra_sanskrit text, mantra_transliteration text,
        ingredients_jsonb jsonb, timing_rules_jsonb jsonb, cost_tier text,
        contraindications text, classical_attestation_text text, scaffold_status text);
      CREATE TABLE remedy_review_queue (
        review_id bigserial PRIMARY KEY, remedy_id text, source_file text,
        raw_data jsonb, validation_errors jsonb, category text,
        queued_at timestamptz DEFAULT now());
      CREATE TABLE asset_registry (
        asset_id text PRIMARY KEY, layer text, sort_order integer, scope text,
        asset_kind text, catalog_status text, is_active boolean, has_writer boolean,
        english_description text, target_table text, count_sql text, size_sql text,
        target_floor bigint, volume_explanation text, depends_on text[],
        integrity_check_sql text);
    `)
    await client.query(`INSERT INTO asset_registry VALUES (
        'bg_remedies','brahmagyan',7,'global','data','CURRENT',true,true,
        $1,'brahma_remedy_corpus','SELECT count(*) FROM brahma_remedy_corpus',
        'SELECT pg_total_relation_size(''brahma_remedy_corpus'')',266,$2,
        ARRAY['bg_texts']::text[],NULL)
    `, [CANONICAL_DESCRIPTION,
      "266 remedies = writer's designed deterministic ceiling: gen_planet_matrix(108) + dosha-linked(102) + legacy(54) + corpus_sweep net-new(2). Floor = achieved count per floors-are-aspirational policy (CLAUDE.md §N.4); ZERO LLM, ZERO fabrication is a hard writer constraint, so this floor cannot be raised without a native-judgment decision to expand the deterministic corpus design."])
    await client.query(`INSERT INTO classical_text_chunks
      SELECT * FROM json_to_recordset($1::json)
      AS source(chunk_id text, text_id text, source_citation text, content_en text)`,
      [JSON.stringify(SOURCE_CHUNKS)])
    return client
  }

  function runWriter(): void {
    execFileSync('python3', ['-c', [
      'import os, pathlib, psycopg',
      'from psycopg.rows import dict_row',
      'from brahmagyan.l0_remedy_corpus import seed_remedy_corpus',
      'from brahmagyan.l0_remedy_loader import load_remedies',
      'conn = psycopg.connect(os.environ["NIRMANA_BG_REMEDIES_INTEGRITY_TEST_DATABASE_URL"], row_factory=dict_row)',
      'seed_remedy_corpus(conn, build_id="migration-608-test", autocommit=False)',
      'load_remedies(pathlib.Path("brahmagyan/remedy_corpus"), conn=conn, file_glob="tantric.yaml", manage_transaction=False)',
      'conn.commit()', 'conn.close()',
    ].join('; ')], { cwd: path.resolve(process.cwd(), 'python-sidecar'),
      env: { ...process.env, NIRMANA_BG_REMEDIES_INTEGRITY_TEST_DATABASE_URL: TEST_DATABASE_URL! },
      stdio: 'pipe' })
  }

  async function detector(client: Client): Promise<boolean> {
    const contract = await client.query<{ integrity_check_sql: string | null }>(
      "SELECT integrity_check_sql FROM asset_registry WHERE asset_id='bg_remedies'")
    expect(contract.rows[0]?.integrity_check_sql).toBeTruthy()
    const result = await client.query(contract.rows[0].integrity_check_sql!)
    return result.rowCount === 1 && Object.values(result.rows[0])[0] === true
  }

  async function sourceSummary(client: Client) {
    return (await client.query(`SELECT count(*)::int AS total,
      count(DISTINCT remedy_id)::int AS distinct_ids,
      md5(string_agg(remedy_id, E'\\n' ORDER BY remedy_id COLLATE "C")) AS id_md5,
      count(*) FILTER (WHERE category='corpus_sweep')::int AS sweep,
      count(*) FILTER (WHERE category='corpus_sweep' AND scaffold_status='live')::int AS sweep_live,
      count(*) FILTER (WHERE category='corpus_sweep' AND scaffold_status='review')::int AS sweep_review,
      count(*) FILTER (WHERE category='tantric')::int AS tantric,
      count(*) FILTER (WHERE category='nakshatra_shanti')::int AS nakshatra
      FROM brahma_remedy_corpus`)).rows[0]
  }

  it('installs and replays before rebuild, then accepts the exact source rebuild', async () => {
    const client = await connectPrepared()
    try {
      await client.query(migration)
      expect(await detector(client)).toBe(false)
      await client.query(migration)
      runWriter()
      expect(await sourceSummary(client)).toEqual({ total: 341, distinct_ids: 341,
        id_md5: EXPECTED_ID_MD5, sweep: 54, sweep_live: 15, sweep_review: 39,
        tantric: 4, nakshatra: 27 })
      expect(await detector(client)).toBe(true)
    } finally { await client.end() }
  })

  it('a governed replay restores stale base and sweep content deterministically', async () => {
    const client = await connectPrepared()
    try {
      await client.query(migration); runWriter()
      const ids = (await client.query(`SELECT
        min(remedy_id) FILTER (WHERE category IS NULL) AS base_id,
        min(remedy_id) FILTER (WHERE category='corpus_sweep') AS sweep_id
        FROM brahma_remedy_corpus`)).rows[0]
      const selected = [ids.base_id, ids.sweep_id]
      const canonical = await client.query(`SELECT remedy_id, to_jsonb(r)-'remedy_id' AS content
        FROM brahma_remedy_corpus r WHERE remedy_id=ANY($1::text[]) ORDER BY remedy_id`, [selected])
      await client.query(`UPDATE brahma_remedy_corpus SET planet='bogus', domain='bogus',
        remedy_type='bogus', prescription_text='stale', mantra_text='stale', gemstone='stale',
        charity_action='stale', day_of_week='stale', color_associated='stale', confidence=0.01,
        source_canonical_id='stale', source_citation='stale', classical_ref='stale',
        category='stale', deity='stale', mantra_sanskrit='stale', mantra_transliteration='stale',
        ingredients_jsonb='{"stale":true}', timing_rules_jsonb='{"stale":true}',
        cost_tier='stale', contraindications='stale', classical_attestation_text='stale',
        scaffold_status='rejected' WHERE remedy_id=ANY($1::text[])`, [selected])
      expect(await detector(client)).toBe(false)
      runWriter()
      const restored = await client.query(`SELECT remedy_id, to_jsonb(r)-'remedy_id' AS content
        FROM brahma_remedy_corpus r WHERE remedy_id=ANY($1::text[]) ORDER BY remedy_id`, [selected])
      expect(restored.rows).toEqual(canonical.rows)
      expect(await detector(client)).toBe(true)
    } finally { await client.end() }
  })

  it('rejects current-like staleness and count-preserving identity/value drift', async () => {
    const client = await connectPrepared()
    try {
      await client.query(migration); runWriter(); await client.query('BEGIN')
      await client.query('SAVEPOINT current_like')
      await client.query(`DELETE FROM brahma_remedy_corpus WHERE remedy_id IN (
        SELECT remedy_id FROM brahma_remedy_corpus WHERE category='corpus_sweep'
        ORDER BY remedy_id COLLATE "C" LIMIT 5);
        UPDATE brahma_remedy_corpus SET scaffold_status='live'
        WHERE category='corpus_sweep' AND scaffold_status='review'`)
      expect(await detector(client)).toBe(false)
      await client.query('ROLLBACK TO SAVEPOINT current_like')
      const corruptions = [
        "UPDATE brahma_remedy_corpus SET remedy_id='count_preserving_bogus_id' WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus)",
        "UPDATE brahma_remedy_corpus SET planet='pluto' WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus)",
        "UPDATE brahma_remedy_corpus SET domain='bogus' WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus)",
        "UPDATE brahma_remedy_corpus SET remedy_type='bogus' WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus)",
        "UPDATE brahma_remedy_corpus SET category='corpus_sweep' WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus WHERE category IS NULL)",
        "UPDATE brahma_remedy_corpus SET prescription_text=' ' WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus)",
        "UPDATE brahma_remedy_corpus SET source_citation=' ' WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus)",
        "UPDATE brahma_remedy_corpus SET classical_ref=' ' WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus)",
        "UPDATE brahma_remedy_corpus SET confidence=NULL WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus)",
        "UPDATE brahma_remedy_corpus SET ingredients_jsonb=NULL WHERE remedy_id=(SELECT min(remedy_id) FROM brahma_remedy_corpus WHERE category='tantric')",
      ]
      for (const corruption of corruptions) {
        await client.query('SAVEPOINT count_preserving_corruption')
        await client.query(corruption)
        expect(await detector(client), corruption).toBe(false)
        await client.query('ROLLBACK TO SAVEPOINT count_preserving_corruption')
      }
      await client.query('ROLLBACK')
    } finally { await client.end() }
  })

  it('fails closed on registry drift without partial canonicalization', async () => {
    const client = await connectPrepared()
    try {
      await client.query("UPDATE asset_registry SET target_floor=999, english_description='drift' WHERE asset_id='bg_remedies'")
      await expect(client.query(migration)).rejects.toThrow(
        'migration 608 refuses unknown bg_remedies registry contract')
      const result = await client.query(`SELECT target_floor, english_description,
        volume_explanation, depends_on, integrity_check_sql FROM asset_registry
        WHERE asset_id='bg_remedies'`)
      expect(result.rows[0]).toMatchObject({ target_floor: '999',
        english_description: 'drift', integrity_check_sql: null })
      expect(result.rows[0].depends_on).toEqual(['bg_texts'])
      expect(result.rows[0].volume_explanation).not.toBe(CANONICAL_VOLUME)
    } finally { await client.end() }
  })
})
